const code = `class TaskChain:
    """Headless TaskChain prototype with dependency tracking."""

    def __init__(self):
        self._tasks = {}
        self._order = []
        self._notifications = []
        self._unblocked = set()

    def _require(self, task_id):
        if task_id not in self._tasks:
            raise KeyError(task_id)
        return self._tasks[task_id]

    def add_task(self, task_id, dependencies=None):
        if task_id in self._tasks:
            raise ValueError("duplicate task id: " + repr(task_id))
        deps = []
        if dependencies is not None:
            for dep in dependencies:
                deps.append(dep)
        for dep in deps:
            if dep not in self._tasks:
                raise KeyError(dep)
        self._tasks[task_id] = {
            "status": "pending",
            "dependencies": deps,
            "comments": [],
        }
        self._order.append(task_id)
        return None

    def start(self, task_id):
        task = self._require(task_id)
        if task["status"] != "pending":
            raise ValueError("task is not pending: " + repr(task_id))
        for dep in task["dependencies"]:
            if self._tasks[dep]["status"] != "completed":
                raise ValueError("dependencies not completed for: " + repr(task_id))
        task["status"] = "in_progress"
        return None

    def complete(self, task_id):
        task = self._require(task_id)
        if task["status"] != "in_progress":
            raise ValueError("task is not in progress: " + repr(task_id))
        task["status"] = "completed"
        self._notifications.append({"kind": "completed", "task_id": task_id})
        for other_id in self._order:
            other = self._tasks[other_id]
            if other["status"] != "pending":
                continue
            if other_id in self._unblocked:
                continue
            if task_id not in other["dependencies"]:
                continue
            if all(self._tasks[d]["status"] == "completed" for d in other["dependencies"]):
                self._unblocked.add(other_id)
                self._notifications.append({"kind": "unblocked", "task_id": other_id})
        return None

    def add_comment(self, task_id, author, text):
        task = self._require(task_id)
        task["comments"].append({"author": author, "text": text})
        return None

    def snapshot(self):
        snap = {}
        for tid, task in self._tasks.items():
            snap[tid] = {
                "status": task["status"],
                "dependencies": list(task["dependencies"]),
                "comments": [
                    {"author": c["author"], "text": c["text"]}
                    for c in task["comments"]
                ],
            }
        return snap

    def notifications(self):
        return [
            {"kind": n["kind"], "task_id": n["task_id"]}
            for n in self._notifications
        ]

    def report(self):
        result = {"pending": [], "in_progress": [], "completed": []}
        for tid, task in self._tasks.items():
            result[task["status"]].append(tid)
        for key in result:
            result[key].sort()
        return result

    def diagram(self):
        lines = ["graph TD"]
        for tid in self._order:
            task = self._tasks[tid]
            if not task["dependencies"]:
                lines.append("    " + str(tid))
            for dep in task["dependencies"]:
                lines.append("    " + str(dep) + " --> " + str(tid))
        return chr(10).join(lines)
